const esc=s=>String(s??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
export function geologicalProfile(r){
 if(!r)return '';
 return `<section class="deposit-profile"><span class="eyebrow">${esc(r.scope)}</span><h3>Coal beneath this landscape</h3>${r.units.length?`<div class="deposit-column" aria-label="${r.orderedProfile?'Published relative order, top to bottom; not to scale':'Documented units; no depth scale or inferred ordering'}">${r.units.map(u=>`<div class="deposit-unit">${esc(u)}</div>`).join('')}</div><p class="micro">${r.orderedProfile?'Top → bottom · spacing not to scale':'Named units · depths and geometry not reconstructed'}</p>`:''}<p>${esc(r.summary)}</p><p class="source-date">${esc(r.sourceBasis)}. Reviewed ${esc(r.reviewedAt)}.</p><p><a href="${esc(r.sourceUrl)}" target="_blank" rel="noopener">${esc(r.sourceTitle)} ↗</a></p><p class="micro">${esc(r.surfaces3D)}. ${esc(r.surfaceMapping)}.</p><details><summary>Geological coverage</summary><p>${esc(r.terrain)}. ${esc(r.boreholeIdsWithin10km.length)} compiled boreholes within 10 km; proximity is not a correlation.</p><p>${r.gaps.map(esc).join('. ')}.</p><a href="./data/mine-geology.json">Download all 35 coverage records</a></details></section>`;
}
